(() => {
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,f)=>{try{return JSON.parse(localStorage.getItem('signoff-v1-'+key))??f}catch{return f}};
const write=(key,v)=>{try{localStorage.setItem('signoff-v1-'+key,JSON.stringify(v));return true}catch{return false}};
const groups=['先建立验收框架','物理与逻辑正确性','性能、供电与可靠性','从报告到最终交付'];
const lessons=[
{id:'standards',title:'什么叫“签核通过”',group:0,desc:'分清工艺规则、芯片规格和项目检查清单。',time:8,tag:'验收框架',body:()=>`
<h2 id="meaning">布线完成以后，还要证明什么？</h2><p>布局布线得到的是一个物理实现。签核要用规定的模型、规则和分析场景，证明这个实现满足项目的交付条件。不同检查分别回答制造、连接、逻辑、速度和可靠性问题。</p>
<div class="flow"><div><b>01 / 能制造</b><p>几何、密度、天线及工艺要求</p></div><div><b>02 / 接得对</b><p>版图连接与最终网表一致</p></div><div><b>03 / 跑得动</b><p>功能、时序与工作条件满足要求</p></div><div><b>04 / 用得久</b><p>供电、温度与寿命满足目标</p></div></div>
<h2 id="rules">三层依据，各管什么？</h2>${table(['依据','通常包含','谁确定'],[['晶圆厂 / PDK','线宽、间距、过孔、天线、密度及可靠性规则；对应 rule deck（检查规则文件）','目标工艺与晶圆厂'],['芯片规格','频率、电压、温度、模式、功耗、面积、寿命和接口要求','设计团队与产品需求'],['项目签核清单','工具版本、角点矩阵、检查配置、交付物和例外审批','项目签核负责人']])}
<div class="callout"><b>没有跨工艺通用的一组“合格数字”</b>不能直接套用“压降低于某个百分比就一定合格”“DRC 少于几条就能流片”。适用规则、预算、场景覆盖和正式批准的例外共同决定验收结论。</div>
<h2 id="roles">谁看哪些结果？</h2><p>物理设计人员修复版图与时序问题；验证团队确认功能与等价性；电源完整性工程师分析 EM/IR；集成和签核负责人审核覆盖范围及最终版本。晶圆厂主要接收制造所需数据和约定报告，项目团队仍负责芯片功能和性能的完整验收。</p>
<h2 id="first-question">拿到结果，先问这四件事</h2><ol><li>这是哪个设计版本、哪套工艺和库？</li><li>覆盖了哪些模式、电压、温度和工艺角？</li><li>检查是否完整结束，是否存在跳过、黑盒或未解析对象？</li><li>所有剩余问题是否已修复，或由有权限的负责人正式批准？</li></ol>${quiz('standard','一份报告写着“PASS”，最先还应确认什么？',['工具界面是否足够专业','输入版本、规则配置和检查覆盖范围','报告文件是否很大'],1,'PASS 是特定输入和配置下的结果。输入或覆盖范围错误，会让通过结论失去验收意义。')}`},
{id:'flow',title:'最终版本与验证流程',group:0,desc:'把版图、网表、寄生参数和报告对应到同一版本。',time:9,tag:'版本与流程',body:()=>`
<h2 id="inputs">一套可以复查的签核输入</h2>${table(['输入','作用','特别留意'],[['GDS / OASIS','最终物理图形与层次','顶层名称、layer map、宏单元和填充是否齐全'],['最终网表','连接与逻辑的参考实现','电源地、ECO、测试与低功耗处理是否一致'],['RC / SPEF 与库模型','反映走线寄生和单元行为','提取角、库角和最终版图匹配'],['SDC / 模式定义','时钟、接口及路径约束','功能与测试模式、例外及约束覆盖'],['PDK / rule deck / 工具配置','定义检查规则和模型解释','工艺选项、金属栈、版本和开关']])}
<h2 id="loop">从候选版本到最终签核</h2><div class="flow"><div><b>01 / 冻结候选</b><p>记录版图、网表、模型与约束版本</p></div><div><b>02 / 提取与分析</b><p>寄生提取、DRC/LVS、STA、LEC、EM/IR</p></div><div><b>03 / ECO 修复</b><p>改线、换单元、补过孔或调整供电</p></div><div><b>04 / 复查归档</b><p>更新相关检查，确认最终交付文件</p></div></div>
<p>这些检查在工程中会交错、并行进行。关键是它们最终指向一致的设计状态。某个检查修改了版图，其他受影响的检查就需要更新。</p>
<h2 id="fill">为什么填充以后还要检查？</h2><p>金属填充用于满足密度等工艺要求，也可能影响耦合电容。要按项目认可的流程纳入最终寄生提取与时序分析，并复查适用的物理规则。部分流程使用 timing-aware fill 或经验证的近似方式，最终仍需满足项目的签核要求。</p>
<div class="callout warning"><b>最后一次小修改，也可能使旧报告失效</b>例如为了修复天线效应加入二极管，可能改变寄生、负载和检查所需的网表处理。不能直接沿用修改前的全部通过报告。</div>
<h2 id="manifest">归档记录示例</h2><pre class="report"><span class="comment"># 教学示例：用于理解版本对应关系</span>
release: candidate_07
layout: chip_final.oas    [checksum]
netlist: chip_final.v     [checksum]
parasitics: rc_corner_set_03
constraints: sdc_release_05
pdk / deck / libs / tools: [exact versions]
reports: [run IDs, timestamps, result summaries]
waivers: [approved IDs and owners]</pre><p class="small">校验值帮助确认文件身份；检查通过仍依赖正确配置与完整运行。</p>`},
{id:'physical',title:'DRC、天线与密度',group:1,desc:'从两条金属线开始，理解制造规则检查。',time:12,tag:'物理验证',body:()=>`
<h2 id="drc">DRC 检查几何和工艺规则</h2><p>DRC（Design Rule Check）检查版图是否符合所选工艺规则，包括最小线宽、间距、过孔包围、面积等。规则可能依赖线宽、平行长度、邻接图形和图形组合，远比简单量两个距离复杂。</p>${drcLab()}
<h2 id="antenna">天线效应为什么也和布线有关？</h2><p>在某些制造步骤中，与晶体管栅极连接的导体可能积累电荷，损伤栅介质。天线规则按工艺定义限制相关导体与栅极的比例；修复可能涉及换层、修改连接顺序或使用适用的保护二极管。</p>
<h2 id="density">密度和金属填充</h2><p>工艺规则可能规定局部窗口内的图形密度、密度梯度及其他条件。通过自动填充补齐图形后，要确认填充自身符合规则，并在后续电气分析中采用项目认可的填充处理方式。</p>
<h2 id="signoff-drc">工具显示 0 条 DRC 就够了吗？</h2><p>布局布线工具内的检查方便早期修复，但检查范围可能与最终签核规则不同。验收应以项目和晶圆厂认可的签核工具、规则版本和配置为依据。</p><div class="callout"><b>常见通过要求</b>适用的强制规则没有未获批准的违规。剩余 marker 必须逐项判断，不能仅凭数量少就接受，也不能随意把问题加入 waiver。</div>${quiz('drc','间距检查通过，能说明电路功能正确吗？',['能，版图已经合法','不能，还需要连接、逻辑和性能等检查'],1,'DRC 覆盖工艺规则，不证明逻辑功能或工作频率。')}`},
{id:'lvs',title:'LVS 与逻辑等价性',group:1,desc:'分清“连接一致”和“逻辑行为一致”。',time:10,tag:'连接与功能',body:()=>`
<h2 id="lvs">LVS：版图里真正接出来的是什么？</h2><p>LVS（Layout Versus Schematic）从版图提取器件和连接，并与参考电路网表比较。在数字后端流程中，参考通常是按签核流程处理后的最终网表。检查包含开路、短路、端口及器件不匹配；适用时还比较器件参数。</p><div class="grid2"><div class="mini"><h3>开路 / Open</h3><p>参考里 A 应连接 B，版图里却断开。常见原因包括未接通的过孔或缺失金属。</p></div><div class="mini"><h3>短路 / Short</h3><p>参考里两个独立网络，在版图里被错误连接。需要定位真正的物理连接位置。</p></div></div>
<h2 id="lec">LEC：优化有没有改变逻辑？</h2><p>逻辑等价检查用形式化方法判断两个设计表示在规定条件下是否具有相同的逻辑行为。后端可能插缓冲、换单元或做 ECO，因此需要确认最终网表仍符合批准的参考设计。</p>${table(['比较','LVS','LEC / 形式等价'],[['主要对象','版图提取的电路 ↔ 参考网表','参考逻辑 ↔ 实现逻辑'],['回答的问题','物理实现是否符合目标电路连接','设计变换是否保持规定的逻辑行为'],['不能独立证明','参考设计本身功能正确、时序达标','版图没有开短路、实际延迟达标']])}
<h2 id="buffers">插了缓冲器，为什么还要检查逻辑？</h2><p>缓冲器在理想逻辑上保持输入值，同时改变驱动能力与实际延迟。后端还可能换单元、插反相器对或做 ECO；这些修改都要保持批准的逻辑行为。</p><div class="buffer-flow"><div><b>预期的优化</b><code>X → BUF → A</code><p>驱动增强，A 仍应收到 X 的逻辑值。</p></div><div><b>可能的连接错误</b><code>Y → BUF → A</code><p>如果最终网表误接到 Y，版图照着实现，LVS 仍可能通过。与参考设计比较的 LEC 可帮助发现差异。</p></div></div><p>LVS 核对版图与最终参考网表；LEC 核对逻辑变换前后的行为；STA 核对实际延迟下的时间要求。三者需要分别检查。</p><h2 id="coverage">检查“通过”也要看覆盖</h2><ul><li>确认宏、存储器和黑盒采用的是批准的模型与处理方式。</li><li>确认电源地、测试模式和低功耗单元被正确解释。</li><li>确认没有未解释的未比较点、无法证明点或被跳过模块。</li><li>ECO 以后更新等价检查，物理连接改变时更新 LVS 等相关检查。</li></ul><div class="callout"><b>LVS 与 LEC 互相补充</b>如果参考网表本身有逻辑错误，版图可以 LVS 通过，芯片仍然可能做错事情。还需要设计验证和规格层面的证据。</div>${quiz('lvs','LVS 已通过，是否可以省略逻辑等价检查？',['可以，它们都在比较电路','不可以，两者验证的关系不同'],1,'LVS 验证版图和参考电路的对应关系；LEC 验证逻辑变换前后的行为一致性。')}`},
{id:'timing',title:'STA 与时序裕量',group:2,desc:'亲手调整周期与延迟，看 setup / hold 如何变化。',time:15,tag:'时序签核',body:()=>`
<h2 id="sta">STA：检查最晚和最早到达</h2><p>静态时序分析根据网表、单元时序模型、寄生参数和约束，分析路径的时间关系。Setup 要求数据别来得太晚；hold 要求数据别变得太早。修复其中一个，可能影响另一个。</p>${timingLab()}
<h2 id="metrics">报告里最常看的三个数</h2>${table(['指标','含义','常见验收目标'],[['WNS / worst slack','最差时序裕量；工具的 WNS 汇总显示方式可能不同','相应检查没有负 slack；部分项目要求正裕量'],['TNS','按工具定义汇总的负时序裕量','0'],['违例端点 / 路径数','仍有时序违例的对象数量，依工具报告口径','0，或仅存在已正式批准的例外']])}
<h2 id="corners">一个角点通过还不够</h2><p>签核通常覆盖多个工作模式和工艺、电压、温度及寄生角组合（MMMC）。功能模式和扫描移位模式的时钟与路径关系不同；慢角与快角也可能影响不同检查。具体场景矩阵由库、工艺和项目方法确定，不能机械地只选“最慢做 setup、最快做 hold”。</p>
<h2 id="other-timing">时序不只有 setup / hold</h2><p>还包括复位等异步控制的 recovery / removal、时钟门控检查、最小脉宽，以及最大转换时间和负载电容等限制。签核要纳入适用的片上变化模型、时钟不确定度、串扰等影响。</p><div class="callout warning"><b>留意被“放过”的路径</b>没有时钟、没有输入输出约束、或错误的 false path 都可能让关键路径漏检。“没有负裕量”必须与约束和覆盖审核一起看。</div>`},
{id:'constraints',title:'约束、串扰与后仿真',group:2,desc:'理解“分析通过”背后的假设是否成立。',time:10,tag:'覆盖与模型',body:()=>`
<h2 id="sdc">SDC 定义了什么条件下算合格</h2><p>SDC 描述时钟周期、生成时钟、输入输出延迟、时钟关系及路径例外。缺少约束会漏掉真实问题，过度约束也会制造并不存在的需求。</p>${table(['检查点','常见问题','审核方式'],[['时钟','漏掉生成时钟或时钟关系不对','对照时钟架构、运行 clock / timing 检查'],['I/O 约束','只约束输入、遗漏输出或最小延迟','对照外部器件和接口预算'],['False path','用例外掩盖真实路径','提供功能依据，审核实际命中对象'],['Multicycle path','只设置 setup，配套 hold 处理不正确','按设计语义及工具要求审核'],['未约束路径','报告无违例，却没有被完整检查','审核 analysis coverage 与 unconstrained 报告']])}
<h2 id="si">串扰会怎样影响结果？</h2><p>相邻线之间存在耦合电容。邻线的切换可能加速或减慢被检查信号，也可能在静止信号上产生噪声。时序签核应按项目方法考虑串扰延迟，并检查适用的噪声限制。</p><div class="grid2"><div class="mini"><h3>时序影响</h3><p>原来裕量很小的路径，计入串扰后可能出现 setup 或 hold 违例。</p></div><div class="mini"><h3>噪声影响</h3><p>即使没有改变最终逻辑值，毛刺幅度与持续时间仍可能触发电气或功能问题。</p></div></div>
<h2 id="gls">还要做带延迟门级仿真吗？</h2><p>项目可针对启动、复位、测试模式、X 传播等场景做门级仿真，必要时回标 SDF 延迟。是否做、做哪些场景取决于验证计划；仿真通常不能穷尽所有路径和时序角，也不能替代 STA、等价性和物理验证。</p>
<h2 id="cdc">跨时钟与低功耗专项</h2><p>异步跨时钟或复位路径还需要 CDC / RDC 等方法验证同步结构和协议。把路径设成 false path，不代表跨域已经安全。多电压域还要验证隔离、保持、level shifter 和电源状态定义，检查范围依项目而定。</p>`},
{id:'power',title:'IR drop、EM 与功耗',group:2,desc:'区分“电压够不够”和“金属能否长期承载”。',time:12,tag:'供电与可靠性',body:()=>`
<h2 id="ir">IR drop：电源走到单元时还剩多少？</h2><p>电源网络有电阻，电流通过就产生压降。静态分析评估稳态负载影响；动态分析进一步考虑随时间变化的切换和供电响应。最低局部电压是否满足单元工作和时序条件，比孤立看一个压降百分比更重要。</p>${irLab()}
<h2 id="em">EM：今天能工作，长期是否可靠？</h2><p>电迁移与电流、温度、材料和寿命条件有关。需要按适用规则检查金属与过孔，具体可能涉及平均、有效值或峰值电流等不同准则。通过加宽金属、增加合规过孔或重分配电流路径修复时，要重新分析相关结果。</p>${table(['检查','主要问题','验收要看'],[['静态 / 动态 IR','供电压降、局部电压最低点','预算、活动场景、供电边界和热点位置'],['EM','金属和过孔长期可靠性','规则模型、温度、寿命及违例分布'],['功耗','动态与漏电功耗是否符合预算','工作负载、活动覆盖、温度电压和模式'],['封装 / 热耦合（适用时）','封装阻抗、温升进一步影响电压与时序','项目要求的封装及热模型']])}
<h2 id="activity">分析是否可信，很依赖活动场景</h2><p>向量驱动分析可使用仿真活动；无向量方法则依赖活动假设和覆盖策略。需要解释场景为什么能覆盖功耗、压降或电流风险，不能只挑一个轻负载片段。</p><div class="callout"><b>不存在默认通用的 IR 百分比或 EM 电流阈值</b>应从工艺可靠性模型、库的工作条件、供电网络、工作负载及项目预算确定限制。教学实验中的数值只说明关系。</div>`},
{id:'reports',title:'报告怎么看、问题怎么定位',group:3,desc:'逐行解读三份示例，避免只看 PASS / FAIL。',time:13,tag:'报告导读',body:()=>`
${caseTeaser()}<h2 id="read-report">先看运行是否有效，再看结果</h2><p>先核对设计版本、工具和规则、corner / mode、结束状态与覆盖摘要，再看违例数量和最差值。排查配置缺失、模型错误和跳过对象以后，才进入设计修复。</p>
<div class="report-tabs" role="group" aria-label="示例报告类型"><button data-report="sta" class="active" aria-pressed="true">时序报告</button><button data-report="drc" aria-pressed="false">DRC 摘要</button><button data-report="ir" aria-pressed="false">电源分析</button></div><div id="report-content" aria-live="polite"></div>
<h2 id="triage">定位问题的顺序</h2><ol><li><b>确认是真问题：</b>版本、约束、模型、规则开关是否正确？</li><li><b>定位对象：</b>路径的起点终点，版图中的违规坐标，或者压降热点。</li><li><b>识别根因：</b>长线、高负载、时钟偏差、缺失过孔、供电瓶颈等。</li><li><b>做最小有效修改：</b>根据根因选择 ECO，避免无依据地全局改参数。</li><li><b>检查连带影响：</b>修 setup 可能影响 hold；加金属可能影响密度和寄生。</li></ol>
<h2 id="waiver">例外记录要包含什么？</h2><p>记录对应规则或对象、影响范围、原因、证据、风险和批准人。工艺规则豁免按晶圆厂及项目流程处理；项目内部路径例外由相应负责人审核。不能用“工具误报”四个字代替分析。</p><div class="callout warning"><b>示例报告用于学习格式</b>这里的报告是独立编写的简化样例，不是商业工具的原始输出，也不是任何真实芯片的签核证据。</div>`},
{id:'checklist',title:'验收清单与交付包',group:3,desc:'把检查结果整理成可以复核的交付证据。',time:10,tag:'验收与归档',body:()=>`
<h2 id="acceptance">逐项确认，再形成签核结论</h2><p>下面是数字 IC 项目的通用起点。实际使用应增删条目，补齐明确的工艺、规格、角点矩阵和负责人。勾选表示你的核对记录，页面不会分析设计文件或自动证明芯片合格。</p>
<div class="check-head"><div><h2 id="check-count">已核对 0 / ${checks.length} 项</h2><p>保存在本浏览器，可导出 Markdown 记录</p></div><button class="btn primary" id="export-checklist">导出核对记录 ↓</button></div><div id="check-items">${checks.map((x,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}"><span><b>${x[0]}</b><small>${x[1]}</small></span></label>`).join('')}</div>
<h2 id="package">通常交付什么？</h2>${table(['交付物','目的'],[['最终 GDS / OASIS、必要宏版图和层映射','制造数据与版图复核'],['最终网表、寄生参数、SDC 与适用模型','集成、分析和复现；按交付边界与 IP 许可提供'],['物理、时序、等价性和 EM/IR 等报告','证明各签核项的结果和覆盖'],['工具 / PDK / 库版本、脚本与配置','复查方法和追踪输入'],['签核摘要、例外清单、批准记录','明确最终结论、责任与剩余问题'],['文件清单与校验值','确认最终设计和报告的版本关系']])}
<h2 id="block-vs-top">模块验收和全芯片流片的区别</h2><p>模块交付要说明 pin、边界、阻挡、供电和时序预算，并提供集成所需视图。全芯片还要完成顶层连接、I/O 与封装接口、适用的 ESD / latch-up / ERC、seal ring 等检查。模块全部通过后，集成层仍需要相应验证。</p><div class="callout"><b>最终签核摘要应该可回答</b>交付的是哪个版本？每项依据是什么？哪些场景通过？还有哪些正式批准的例外？谁确认了最终数据与报告一致？</div>`},
{id:'practice',title:'自测、术语与模拟芯片差异',group:3,desc:'用几个场景检验理解，再看不同芯片的侧重点。',time:10,tag:'自测与拓展',body:()=>`
<h2 id="practice-questions">三个常见判断题</h2>${quiz('q1','DRC、LVS 都通过，目标 1 GHz 就一定能跑吗？',['能，物理实现已通过','不能，还需时序和供电等签核'],1,'DRC/LVS 不证明性能。需要在规定模式与角点下检查时序，并验证供电等工作条件。')}${quiz('q2','只有典型工艺角的 setup 通过，可以流片吗？',['可以，典型角最有代表性','不能据此签核，应满足规定的完整场景矩阵'],1,'典型角不能代替签核要求的工艺、电压、温度、寄生和工作模式覆盖。')}${quiz('q3','最后只改了一根电源线，可以保留所有旧报告吗？',['可以，功能没改','应分析影响并更新受影响的检查'],1,'供电连接、几何规则、密度、寄生和 EM/IR 都可能受到影响。最终报告需要对应最终交付状态。')}
<h2 id="analog">模拟 / 射频 IC 需要加什么？</h2><p>DRC、LVS、寄生提取、可靠性等仍重要，但性能验收通常更依赖寄生提取后的电路仿真。例如运放看增益、带宽、相位裕量和噪声；ADC 看精度、线性度和动态性能；RF 电路还可能需要无源器件与互连的电磁分析。</p><p>还要按规格覆盖 PVT、适用的失配 / Monte Carlo、老化和工作条件。数字 STA 的检查项不能直接覆盖这些模拟性能要求。</p>
<h2 id="glossary">常用术语速查</h2><dl class="glossary">${[['Signoff','签核：按规定输入、模型和场景完成最终验收。'],['PDK','工艺设计套件，提供工艺相关模型、规则与支持数据。'],['DRC / LVS','制造规则检查 / 版图与参考电路一致性检查。'],['PEX / SPEF','寄生提取 / 常见寄生参数交换格式。'],['STA / SDC','静态时序分析 / 常见设计约束格式。'],['MMMC','多模式、多工艺角分析，具体矩阵按项目定义。'],['WNS / TNS','最差负裕量相关指标 / 总负时序裕量，统计口径看工具。'],['LEC','逻辑等价性检查。'],['IR / EM','电源压降 / 电迁移可靠性。'],['ECO','工程变更，常用于后期局部修复。'],['Waiver','对特定问题正式记录并批准的例外处理。'],['Tapeout','向制造环节提交最终芯片设计数据。']].map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl>
<h2 id="next-step">建议练习顺序</h2><ol><li>在间距实验中制造一次违规，并说明它为什么不等于 LVS 错误。</li><li>在时序实验中构造“setup 通过、hold 失败”的情况。</li><li>在示例报告中找到配置缺失，区分它与真实设计违例。</li><li>导出验收清单，补充你所在项目的工艺、模式和具体阈值。</li></ol>`}
];
function table(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function quiz(id,title,answers,right,explanation){return `<div class="quiz" data-right="${right}" data-explain="${esc(explanation)}"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><p>${title}</p>${answers.map((a,i)=>`<button type="button" data-answer="${i}">${String.fromCharCode(65+i)}. ${a}</button>`).join('')}<div class="quiz-feedback" aria-live="polite"></div></div>`}
const checks=[['设计与输入版本一致','版图、最终网表、寄生、约束及模型可追溯到同一最终状态。'],['检查配置与规则适用','工具、PDK / deck、工艺选项与金属栈均已核对。'],['DRC、天线及密度通过','适用强制规则无未获批准的违规，最终填充已纳入流程。'],['LVS 通过','没有未解释的不匹配、开短路或缺失对象。'],['逻辑等价性通过','参考正确；黑盒和未比较对象均按项目方法审核。'],['时序场景覆盖完整','功能 / 测试模式，适用 PVT、RC 角和变化模型齐全。'],['时序与电气限制满足','Setup / hold 等所有适用检查达标，串扰按规定纳入。'],['约束与路径例外已审核','时钟和 I/O 完整，无意外未约束路径；例外有依据。'],['IR drop 与 EM 满足要求','活动场景、封装 / 供电边界、温度与寿命假设已审核。'],['功耗及专项检查满足要求','按范围完成低功耗、DFT、CDC / RDC、ESD / ERC 等检查。'],['最终交付包完整','顶层、宏、层映射、脚本、报告与校验清单均已归档。'],['剩余例外正式批准','每项包含对象、原因、证据、影响范围与批准人。']];
function drcLab(){return `<div class="lab" data-lab="drc"><div class="lab-head"><b>实验 01 / 两条金属线的间距</b><span>简化几何 · 非工艺参数</span></div><div class="lab-body"><div class="lab-visual"><svg viewBox="0 0 500 260" role="img" aria-label="两段金属线的间距与示例要求对比"><defs><pattern id="drc-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#23415c" stroke-width=".6"/></pattern></defs><rect width="500" height="260" fill="url(#drc-grid)"/><rect x="55" y="50" width="390" height="45" rx="3" fill="#3dc3d7"/><rect id="drc-wire" x="55" y="150" width="390" height="45" rx="3" fill="#7e9cd5"/><path id="drc-measure" stroke="white" stroke-width="2"/><text x="65" y="35" fill="#9cbcd8" font-size="12">M2 · 同层导体</text><text id="drc-svg-label" x="260" y="130" fill="white" font-size="14" text-anchor="middle"></text></svg></div><div class="settings"><label for="drc-space">实际间距 S <output id="drc-space-val"></output></label><input id="drc-space" type="range" min="30" max="150" value="60" step="5"><label for="drc-rule">示例最小间距 <output id="drc-rule-val"></output></label><input id="drc-rule" type="range" min="40" max="120" value="80" step="5"><div class="result" id="drc-result" aria-live="polite"></div></div></div><p class="lab-note">仅检查两条平行线之间的一个间距条件。单位 nm，数值为教学假设；真实规则可能随宽度、并行长度与周围图形变化。</p></div>`}
function timingLab(){return `<div class="lab" data-lab="timing"><div class="lab-head"><b>实验 02 / Setup 与 hold 的两个方向</b><span>同周期时钟 · 零偏差简化模型</span></div><div class="lab-body"><div class="lab-visual"><svg viewBox="0 0 500 260" role="img" aria-label="发射寄存器通过组合逻辑到捕获寄存器的时序路径"><rect x="35" y="72" width="95" height="100" rx="6" fill="#193e60" stroke="#6acde0"/><rect x="370" y="72" width="95" height="100" rx="6" fill="#193e60" stroke="#6acde0"/><path d="M130 122H190M310 122H370" fill="none" stroke="#69d9dd" stroke-width="3"/><rect x="190" y="93" width="120" height="58" rx="5" fill="#285f8c"/><g fill="#e2effb" text-anchor="middle" font-size="13"><text x="82" y="116">发射</text><text x="82" y="139">寄存器</text><text x="418" y="116">捕获</text><text x="418" y="139">寄存器</text><text x="250" y="128">组合逻辑 + 线</text></g><path d="M82 210V172M418 210V172M82 210H418" fill="none" stroke="#7397b5" stroke-dasharray="4 4"/><text x="250" y="235" fill="#a5c1d9" text-anchor="middle" font-size="12">同一理想时钟 · 不含串扰 / 变化 / 不确定度</text><text id="timing-svg-label" x="250" y="48" fill="#75dfe7" text-anchor="middle" font-size="14"></text></svg></div><div class="settings"><label for="period">时钟周期 T <output id="period-val"></output></label><input id="period" type="range" min="500" max="1800" value="1000" step="25"><label for="delay-max">数据最大路径延迟 <output id="delay-max-val"></output></label><input id="delay-max" type="range" min="200" max="1500" value="950" step="25"><label for="delay-min">数据最小路径延迟 <output id="delay-min-val"></output></label><input id="delay-min" type="range" min="10" max="180" value="70" step="5"><div class="result" id="timing-result" aria-live="polite"></div></div></div><p class="lab-note">单位 ps。最大 / 最小数据延迟包含 clock-to-Q、逻辑及连线。固定 setup = 100 ps、hold = 60 ps。Setup slack = T − Dmax − 100；hold slack = Dmin − 60。真实 STA 还要处理时钟偏差、变化、串扰及路径例外等。</p></div>`}
function irLab(){return `<div class="lab" data-lab="ir"><div class="lab-head"><b>实验 03 / 电流、电阻与局部电压</b><span>直流集总模型 · 非 EM/IR 求解器</span></div><div class="lab-body"><div class="lab-visual"><svg viewBox="0 0 500 260" role="img" aria-label="供电通过等效电阻到负载的直流示意"><circle cx="65" cy="120" r="35" fill="#1f486a" stroke="#77d4e1"/><text x="65" y="125" fill="white" text-anchor="middle" font-size="14">VDD</text><path d="M100 120H175L185 100L200 140L215 100L230 140L245 100L260 140L275 120H360" fill="none" stroke="#77d4e1" stroke-width="3"/><rect x="360" y="80" width="100" height="80" rx="5" fill="#275d84"/><text x="410" y="125" text-anchor="middle" fill="white" font-size="14">负载</text><text id="ir-svg-label" x="250" y="55" fill="#7edce8" font-size="17" text-anchor="middle"></text><text x="225" y="180" text-anchor="middle" fill="#acc6dc" font-size="12">ΔV = I × R</text><text x="250" y="230" text-anchor="middle" fill="#acc6dc" font-size="12">只演示单一等效路径，不包含瞬态和分布网络</text></svg></div><div class="settings"><label for="ir-current">电流 I <output id="ir-current-val"></output></label><input id="ir-current" type="range" min="100" max="1500" value="700" step="50"><label for="ir-resistance">等效电阻 R <output id="ir-resistance-val"></output></label><input id="ir-resistance" type="range" min="10" max="150" value="80" step="5"><div class="result" id="ir-result" aria-live="polite"></div></div></div><p class="lab-note">固定 VDD = 0.80 V。输入单位 mA 与 mΩ；只计算压降，不设置合格阈值。真实签核需分布式电源网络、活动覆盖、适用的封装及动态模型。</p></div>`}
const heroSvg=`<svg viewBox="0 0 460 330" role="img" aria-label="最终芯片候选版图通过物理、时序、逻辑和供电四项独立检查的教学示意"><defs><pattern id="hero-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" stroke="#294863" stroke-width=".5" fill="none"/></pattern></defs><rect x="15" y="30" width="240" height="250" rx="8" fill="url(#hero-grid)" stroke="#547c9e"/><rect x="38" y="55" width="85" height="64" fill="#264b6c" stroke="#5987a9"/><text x="80" y="92" fill="#a9c8e1" font-size="12" text-anchor="middle">SRAM</text><g fill="#36688d">${Array.from({length:24},(_,i)=>`<rect x="${38+(i%6)*30}" y="${148+Math.floor(i/6)*26}" width="22" height="13" rx="2"/>`).join('')}</g><g fill="none" stroke-width="3"><path d="M80 119V180H218V98H153" stroke="#4bceda"/><path d="M38 205H180V62H224V252H65V225" stroke="#7e9ddb"/><path d="M65 148V130H202V226H110V174" stroke="#409bac"/></g><path d="M255 155H282M282 70V250M282 70H310M282 130H310M282 190H310M282 250H310" stroke="#547c9e" fill="none"/><g fill="#183750" stroke="#436682">${[46,106,166,226].map(y=>`<rect x="310" y="${y}" width="133" height="46" rx="6"/>`).join('')}</g><g fill="#b9d6e9" font-size="13"><text x="328" y="74">DRC / LVS</text><text x="328" y="134">时序 STA</text><text x="328" y="194">等价性 LEC</text><text x="328" y="254">EM / IR</text></g><g fill="#63dce0">${[69,129,189,249].map(y=>`<circle cx="429" cy="${y}" r="3"/>`).join('')}</g><text x="135" y="307" text-anchor="middle" font-size="11" fill="#94b0c9">同一版本 · 多个验证维度</text></svg>`;
for(const [lessonId,caseId] of [['physical','drc'],['timing','timing'],['power','power']]){const l=lessons.find(x=>x.id===lessonId),original=l.body;l.body=()=>original()+window.SignoffCases.block(caseId,true);}
const byId=Object.fromEntries(lessons.map((l,i)=>[l.id,{...l,index:i}]));let current='home';
function nav(){const done=read('done',[]);$('#chapters').innerHTML=groups.map((g,i)=>`<details class="group" open><summary>0${i+1} · ${g}</summary>${lessons.filter(l=>l.group===i).map(l=>`<a href="#${l.id}" class="${current===l.id?'current':''}" ${current===l.id?'aria-current="page"':''}><b>${String(lessons.indexOf(l)+1).padStart(2,'0')}</b><span>${l.title}</span><i>${done.includes(l.id)?'✓':''}</i></a>`).join('')}</details>`).join('');$('#progress-label').textContent=done.length+' / 10';$('#progress').style.width=done.length*10+'%';$$('.topnav a').forEach(a=>{const id=a.hash.slice(1);a.classList.toggle('active',id===current||(id==='home'&&byId[current]&&!['reports','checklist'].includes(current)))});}
function home(){const done=read('done',[]),next=lessons.find(l=>!done.includes(l.id))??lessons[0];return `<section><div class="hero"><div><span class="eyebrow">FROM ROUTING TO SIGNOFF</span><h1>布线完成以后，<br>怎样证明芯片合格？</h1><p>从制造规则到时序、功能与供电可靠性。<br>读懂检查结果，也读懂“通过”背后的条件。</p><div class="hero-actions"><a class="btn" href="#${next.id}">${done.length?'继续学习':'开始第一节'} <span>→</span></a><a href="#checklist">直接查看验收清单 ↗</a></div><div class="facts"><span><b>10</b> 节签核主线</span><span><b>3</b> 组交互实验</span><span><b>12</b> 项验收核对</span></div></div><div class="hero-figure">${heroSvg}<div class="figure-caption">签核关系教学示意 · 非真实设计数据</div></div></div><div class="section-head"><div><span class="eyebrow">YOUR LEARNING PATH</span><h2>先知道验什么，再学会怎么看。</h2></div><span>适用于数字 IC / ASIC 后端入门</span></div><div class="path-grid">${groups.map((g,i)=>`<article class="path"><div class="path-label"><span>PHASE 0${i+1}</span><span>${lessons.filter(l=>l.group===i).length} 节</span></div><h3>${g}</h3><p>${['明确标准来源，建立同一最终版本的证据链。','分别检查制造规则、连接和逻辑行为。','理解速度、工作条件与长期可靠性。','读懂结果、定位问题、整理交付证据。'][i]}</p>${lessons.filter(l=>l.group===i).map(l=>`<a href="#${l.id}"><span>${String(lessons.indexOf(l)+1).padStart(2,'0')}</span>${l.title}<b>${done.includes(l.id)?'✓':'→'}</b></a>`).join('')}</article>`).join('')}</div><div class="section-head"><div><span class="eyebrow">LEARN BY DOING</span><h2>改变一个参数，看见一种约束。</h2></div><a href="#labs">全部实验 →</a></div><div class="feature-row"><a class="feature" href="#physical/drc"><span>01 / GEOMETRY</span><h3>两条线，间距够吗？</h3><p>移动金属线，观察规则如何触发。</p></a><a class="feature" href="#timing/sta"><span>02 / TIMING</span><h3>数据太晚，还是太早？</h3><p>分别制造 setup 和 hold 违例。</p></a><a class="feature" href="#power/ir"><span>03 / POWER</span><h3>电源走到负载还剩多少？</h3><p>调节电流和电阻，观察压降关系。</p></a></div>${caseTeaser()}<div class="section-head"><div><span class="eyebrow">READ · CHECK · DELIVER</span><h2>把“通过”变成可复核的证据。</h2></div></div><div class="grid2"><a class="feature" href="#reports"><span>REPORT READER</span><h3>三份简化报告，逐项读懂</h3><p>识别负裕量、未完成检查与电源热点。</p></a><a class="feature" href="#checklist"><span>ACCEPTANCE CHECKLIST</span><h3>12 项核对与可导出记录</h3><p>从最终输入一直检查到例外批准和交付包。</p></a></div><div class="callout"><b>从通用框架走向具体项目</b>这里解释检查方法与常见要求。实际阈值以目标工艺、库、规格和项目签核清单为准；模拟 / RF 的不同侧重点见第 10 节。</div></section>`}
function caseTeaser(){return `<div class="case-teaser"><div><span class="eyebrow">REAL ENGINEERING CASES</span><h3>把报告和真实版图，对起来看。</h3><p>GCD 短路排查、Ibex 负时序裕量、电源网络与 IR 报告。可放大原图，点击编号逐项阅读。</p><a class="btn primary" href="#cases">打开 3 个真实案例 →</a></div><a href="#cases/real-timing"><img src="assets/clock_path_update.webp" alt="Ibex 真实时序报告与高亮路径预览" loading="lazy"></a></div>`}
function notes(id){return `<div class="notes"><label for="lesson-notes">我的本节笔记</label><p>记录关键结论、项目要求和待确认的问题。</p><textarea id="lesson-notes" placeholder="例如：我们项目要求覆盖哪些 mode / corner？">${esc(read('note-'+id,''))}</textarea><div class="note-status" id="note-status" aria-live="polite">笔记保存在本浏览器</div></div>`}
function chapter(l){const i=l.index,done=read('done',[]);return `<article class="chapter"><div class="crumb"><a href="#home">学习路径</a>　/　${groups[l.group]}　/　${String(i+1).padStart(2,'0')}</div><span class="eyebrow">LESSON ${String(i+1).padStart(2,'0')} / ${l.tag}</span><h1>${l.title}</h1><p class="lead">${l.desc}</p><div class="meta"><span>建议阅读 ${l.time} 分钟</span><span>数字 IC / ASIC</span><span>${done.includes(l.id)?'已标记学完':'可记笔记与保存进度'}</span></div>${l.body()}${notes(l.id)}<div class="chapter-end"><a href="#sources">资料依据与范围 ↗</a><button class="btn primary" id="complete" aria-pressed="${done.includes(l.id)}">${done.includes(l.id)?'已学完 ✓ · 点击撤销':'标记本节已学完 ✓'}</button></div><nav class="pagination" aria-label="前后章节">${i?`<a href="#${lessons[i-1].id}"><small>← 上一节</small>${lessons[i-1].title}</a>`:'<a href="#home">← 学习路径</a>'}${i<lessons.length-1?`<a href="#${lessons[i+1].id}"><small>下一节 →</small>${lessons[i+1].title}</a>`:'<a href="#checklist">复习验收清单 →</a>'}</nav></article>`}
function reports(kind='sta'){
const data={sta:{code:`<span class="comment"># 教学报告 · 简化格式 · 非真实芯片</span>\nDesign      : demo_chip / candidate_07\nScenario    : FUNC_SLOW_RC_MAX\nCheck       : setup\nStartpoint  : u_src/Q\nEndpoint    : u_dst/D\nData arrival time    1.050 ns\nData required time   1.000 ns\n<span class="bad">Slack (VIOLATED)    -0.050 ns</span>\n<span class="comment">Coverage: hold and other scenarios not shown</span>`,rows:[['Scenario','只显示一个功能慢角的 setup，不能代表全部签核场景。'],['Arrival / Required','数据到达 1.050 ns，要求不晚于 1.000 ns。'],['Slack = −0.050 ns','晚了 50 ps。先检查约束及路径，再定位单元、走线和时钟的贡献。'],['Coverage','还要查看 hold、其他模式和角点，以及约束覆盖。']]},drc:{code:`<span class="comment"># 教学报告 · 简化格式 · 非真实芯片</span>\nDesign      : demo_chip / candidate_07\nDeck        : example_rules / rev_03\nM2.MIN_SPACE          4 markers\nVIA1.ENCLOSURE        1 marker\n<span class="good">ANTENNA                0 markers</span>\n<span class="bad">DENSITY                SKIPPED</span>\nRun status  : completed with warnings\nWaivers     : none`,rows:[['5 个 marker','表示检查器的标记数，不必然等于 5 个独立根因。需要定位和归类。'],['ANTENNA = 0','仅说明本次已启用的对应检查没有标记。'],['DENSITY = SKIPPED','密度检查未执行，不能宣称完整物理签核通过。'],['Completed with warnings','运行结束不等于设计通过；还要审核警告和覆盖。']]},ir:{code:`<span class="comment"># 教学报告 · 简化格式 · 非真实芯片</span>\nAnalysis     : static DC\nSupply       : 0.800 V\nActivity     : assumed profile A\nWorst drop   : 0.064 V (8.0%)\nMin voltage  : 0.736 V\nHotspot      : tile_18 / x=320 y=460\n<span class="bad">Budget       : not provided</span>\n<span class="comment">Dynamic / EM / package effects: not covered</span>`,rows:[['64 mV / 8%','是计算结果，不是通用合格线。没有预算就不能作出通过结论。'],['Min voltage','需检查局部电压是否符合库和时序工作条件。'],['Activity','假设活动需要覆盖依据，轻负载可能漏掉热点。'],['Analysis scope','这里只做静态直流；不能代替动态 IR 或 EM 签核。']]}};
const d=data[kind];$('#report-content').innerHTML=`<pre class="report">${d.code}</pre>${table(['报告字段','如何理解'],d.rows)}`;
$$('[data-report]').forEach(b=>{b.classList.toggle('active',b.dataset.report===kind);b.setAttribute('aria-pressed',b.dataset.report===kind?'true':'false')});}
function labs(){return `<article class="chapter"><div class="crumb"><a href="#home">学习路径</a> / 交互实验</div><span class="eyebrow">INTERACTIVE LABS</span><h1>从一个参数，理解一次检查。</h1><p class="lead">三个实验分别说明几何、时间和供电关系。所有数值均为教学假设。</p><h2 id="geometry-lab">01 / 间距实验</h2>${drcLab()}<a href="#physical">回到 DRC 讲义 →</a><h2 id="timing-lab">02 / 时序预算</h2>${timingLab()}<a href="#timing">回到 STA 讲义 →</a><h2 id="power-lab">03 / 直流压降</h2>${irLab()}<a href="#power">回到供电讲义 →</a></article>`}
function sources(){return `<article class="chapter"><div class="crumb"><a href="#home">学习路径</a> / 资料来源</div><span class="eyebrow">SOURCES & SCOPE</span><h1>资料依据与适用范围</h1><p class="lead">主线面向数字 IC / ASIC 的布局布线后签核入门。内容独立编写，以下官方资料支持检查定义和方法范围。</p><ul class="source-list">${[
['OpenROAD · Flow Scripts Tutorial','https://openroad-flow-scripts.readthedocs.io/en/latest/tutorials/FlowTutorial.html','3 个工程实例及原始工具截图；短路修复、时序路径和 GCD 静态 IR 数值。'],
['OpenROAD · IR Drop Analysis','https://openroad.readthedocs.io/en/latest/main/src/psm/README.html','静态 IR 分析、浮空供电条带和分段电流输出的适用范围。'],
['Synopsys · Physical Verification','https://www.synopsys.com/implementation-and-signoff/physical-verification.html','DRC、LVS、金属填充与物理签核范围。'],
['Synopsys · What Is LVS?','https://www.synopsys.com/glossary/what-is-layout-versus-schematic-checking.html','版图提取、参考电路比较以及常见不匹配类型。'],
['SkyWater SKY130 · Process Design Rules','https://skywater-pdk.readthedocs.io/en/main/rules.html','公开工艺规则示例；不能作为其他工艺的设计标准。'],
['SkyWater SKY130 · Antenna Rules','https://skywater-pdk.readthedocs.io/en/main/rules/antenna.html','天线比、制造过程和相关保护结构的规则示例。'],
['Synopsys · PrimeTime Datasheet','https://www.synopsys.com/content/dam/synopsys/implementation%26signoff/datasheets/primetime-ds.pdf','多模式多角、时序、串扰和变化感知分析。'],
['Synopsys · PrimeTime Foundation','https://training.synopsys.com/learn/courses/1001/primetime','约束完整性，setup、hold、recovery、removal 等检查。'],
['Synopsys · Equivalence Checking & ECO','https://www.synopsys.com/blogs/chip-design/equivalence-checking-and-functional-eco.html','逻辑等价检查与后期设计变更。'],
['Synopsys · Design Signoff','https://www.synopsys.com/implementation-and-signoff/signoff.html','功耗、IR drop、EM、可靠性及签核方法范围。'],
['Synopsys · Totem','https://www.synopsys.com/implementation-and-signoff/signoff/totem.html','模拟、混合信号及全定制设计的 EM/IR 分析。']
].map(([a,b,c])=>`<li><a href="${b}" target="_blank" rel="noopener">${a} ↗</a><p>${c}</p></li>`).join('')}</ul><p class="small">截图版权属于 OpenROAD 项目及其原始权利人；页面仅叠加编号用于教学导读。<a href="assets/CREDITS.txt" target="_blank" rel="noopener">逐图来源与说明 ↗</a></p><h2 id="scope">内容边界</h2><ul><li>未指定工艺、库、芯片规格或 EDA 版本，因此不提供实际制造阈值或命令脚本。</li><li>三个交互实验为简化模型；示例报告不是商业工具原始输出。</li><li>验收清单是通用起点，项目需补齐具体要求和批准流程。</li><li>第 10 节介绍模拟 / RF 的差异，不构成完整模拟签核清单。</li></ul><h2 id="privacy">学习记录</h2><p>笔记、勾选和学习进度仅保存在当前浏览器本地，没有上传服务。清理浏览器数据会删除记录；更换设备不会自动同步。可在验收清单中导出核对记录。</p><p class="small">资料核对日期：2026-10-14。具体流片始终采用目标项目批准的工艺和工具版本。</p></article>`}
function initLabs(){
if($('#drc-space')){const update=()=>{const s=+$('#drc-space').value,r=+$('#drc-rule').value,good=s>=r,y=95+s*.65;$('#drc-space-val').textContent=s+' nm';$('#drc-rule-val').textContent=r+' nm';$('#drc-wire').setAttribute('y',y);$('#drc-measure').setAttribute('d',`M250 95V${y}M243 95H257M243 ${y}H257`);$('#drc-svg-label').setAttribute('y',Math.max(120,95+s*.65/2));$('#drc-svg-label').setAttribute('x',328);$('#drc-svg-label').textContent=s+' nm';$('#drc-result').innerHTML=`<span class="pill ${good?'pass':'fail'}">${good?'本项满足':'间距违规'}</span><strong class="${good?'pass-text':'fail-text'}">${s-r>=0?'+':''}${s-r} nm</strong><span>实际间距 − 示例最小间距</span>`};$('#drc-space').oninput=update;$('#drc-rule').oninput=update;update()}
if($('#period')){const update=()=>{const t=+$('#period').value,max=+$('#delay-max').value,min=+$('#delay-min').value,setup=t-max-100,hold=min-60;[['period',t],['delay-max',max],['delay-min',min]].forEach(([k,v])=>$('#'+k+'-val').textContent=v+' ps');$('#timing-svg-label').textContent=`T = ${t} ps / f ≈ ${(1000/t).toFixed(2)} GHz`;$('#timing-result').innerHTML=`<div>Setup slack <b class="${setup>=0?'pass-text':'fail-text'}">${setup>=0?'+':''}${setup} ps · ${setup>=0?'满足':'违规'}</b></div><div>Hold slack <b class="${hold>=0?'pass-text':'fail-text'}">${hold>=0?'+':''}${hold} ps · ${hold>=0?'满足':'违规'}</b></div><small>在本模型下，延长周期只改变 setup。</small>`};['period','delay-max','delay-min'].forEach(k=>$('#'+k).oninput=update);update()}
if($('#ir-current')){const update=()=>{const i=+$('#ir-current').value,r=+$('#ir-resistance').value,mv=i*r/1000,v=.8-mv/1000;$('#ir-current-val').textContent=i+' mA';$('#ir-resistance-val').textContent=r+' mΩ';$('#ir-svg-label').textContent='负载电压 '+v.toFixed(3)+' V';$('#ir-result').innerHTML=`压降 ΔV<strong>${mv.toFixed(1)} mV</strong><span>占供电 ${((mv/800)*100).toFixed(2)}% · 负载电压 ${v.toFixed(3)} V</span><br><small>没有项目预算，不能判断是否合格。</small>`};$('#ir-current').oninput=update;$('#ir-resistance').oninput=update;update()}}
function initChecklist(){if(!$('#check-items'))return;const state=read('checks',[]);$$('[data-check]').forEach(e=>{e.checked=state.includes(+e.dataset.check);e.onchange=()=>{const list=$$('[data-check]').filter(x=>x.checked).map(x=>+x.dataset.check);write('checks',list);update()}});const update=()=>{$('#check-count').textContent='已核对 '+$$('[data-check]').filter(x=>x.checked).length+' / '+checks.length+' 项'};update();$('#export-checklist').onclick=()=>{const done=$$('[data-check]').filter(x=>x.checked).map(x=>+x.dataset.check);const text=`# 数字 IC 签核核对记录\n\n导出时间：${new Date().toISOString()}\n\n项目：待填写\n设计版本：待填写\n工艺 / PDK：待填写\n角点矩阵：待填写\n负责人：待填写\n\n说明：勾选表示人工核对记录，不是自动分析结论。\n\n${checks.map((x,i)=>`- [${done.includes(i)?'x':' '}] ${x[0]}\n  ${x[1]}`).join('\n')}\n\n## 我的验收笔记\n\n${read('note-checklist','（未填写）')}\n\n## 报告与批准记录\n\n待填写报告路径、校验值、waiver 编号与批准人。\n`;download('ic-signoff-checklist.md',text,'text/markdown;charset=utf-8')};}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){let [id,anchor]=(location.hash.slice(1)||'home').split('/');if(!byId[id]&&!['home','labs','sources','cases'].includes(id))id='home';current=id;document.body.classList.toggle('with-toc',id!=='home');$('#page').innerHTML=id==='home'?home():id==='labs'?labs():id==='sources'?sources():id==='cases'?window.SignoffCases.hub():chapter(byId[id]);document.title=(byId[id]?.title??({home:'从布线完成到流片验收',labs:'交互实验',sources:'资料依据',cases:'真实案例与截图'}[id]))+' · 芯片签核学习室';nav();$('#toc').innerHTML=id==='home'?'':`<strong>本节内容</strong>${$$('#page h2[id]').filter(h=>h.id!=='check-count').map(h=>`<a href="#${id}/${h.id}">${h.textContent}</a>`).join('')}<div class="toc-end"><a href="#home">← 学习路径总览</a><a href="#checklist">打开验收清单 →</a></div>`;$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('#menu').setAttribute('aria-expanded','false');initLabs();initChecklist();if($('#report-content'))reports();$$('[data-report]').forEach(b=>b.onclick=()=>reports(b.dataset.report));$$('[data-answer]').forEach(b=>b.onclick=()=>{const q=b.closest('.quiz'),correct=+b.dataset.answer===+q.dataset.right;$('.quiz-feedback',q).innerHTML=`<b class="${correct?'pass-text':'fail-text'}">${correct?'回答正确。':'再想一想。'}</b> ${q.dataset.explain}`;$$('button',q).forEach(x=>x.setAttribute('aria-pressed',x===b?'true':'false'))});if($('#lesson-notes'))$('#lesson-notes').oninput=e=>{$('#note-status').textContent=write('note-'+id,e.target.value)?'已保存到本浏览器':'浏览器未允许保存，请复制笔记留存'};if($('#complete'))$('#complete').onclick=()=>{let done=read('done',[]);done=done.includes(id)?done.filter(x=>x!==id):[...done,id];write('done',done);const yes=done.includes(id);$('#complete').textContent=yes?'已学完 ✓ · 点击撤销':'标记本节已学完 ✓';$('#complete').setAttribute('aria-pressed',yes?'true':'false');nav()};requestAnimationFrame(()=>{if(anchor&&document.getElementById(anchor))document.getElementById(anchor).scrollIntoView();else window.scrollTo(0,0)});}
function search(){const q=$('#search-input').value.trim().toLowerCase();const items=lessons.map(l=>({...l,text:(l.title+' '+l.desc+' '+l.body().replace(/<[^>]+>/g,' ')).toLowerCase()})).filter(l=>!q||l.text.includes(q));$('#search-results').innerHTML=items.length?items.map(l=>`<a class="search-hit" href="#${l.id}">${l.title}<small>${l.desc}</small></a>`).join(''):'<p class="small">没有找到匹配内容，试试“时序”“规则”或“电源”。</p>';$$('.search-hit').forEach(a=>a.onclick=()=>$('#search-dialog').close())}
function openSearch(){$('#search-dialog').showModal();search();$('#search-input').focus()}
$('#menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#scrim').hidden=!open;$('#menu').setAttribute('aria-expanded',String(open))};$('#scrim').onclick=()=>{$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('#menu').setAttribute('aria-expanded','false')};$('#search-open').onclick=openSearch;$('#close-search').onclick=()=>$('#search-dialog').close();$('#search-input').oninput=search;document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('#menu').setAttribute('aria-expanded','false')}});window.addEventListener('hashchange',render);render();
})();
